import{_ as i,O as a,o as r,c as d,a as n,i as s,f as o}from"./chunks/framework.fmIt2z2h.js";const f=JSON.parse('{"title":"A.2　HV02 边界与接口（完整接口卡）","description":"","frontmatter":{"title":"A.2　HV02 边界与接口（完整接口卡）","xkChars":1367,"xkLessons":{"A.2":{"title":"A.2　HV02 边界与接口（完整接口卡）","lead":"HV02把正式边界、实际通行与指定通道因果效应分开；成员身份、影响范围都不能自动变成同意或管辖权。","explanation":["原文定位：第3634—3699行，原站定位/theory/appendix-a/a-02#section-a-2。本题切片及完整用户原稿均在source目录，可逐字回查。","短引文：“成员身份等于同意”是禁止跳跃。HV02不是只画一条内外线，而是同时登记成员、资源、信息、权利、责任和跨界接口。正式名单、实际资源控制、技术开放和现实通行可能不同；把这些混同或排除项不可见时，相关判断应暂停。[T-main]","上游推理依赖HV01，但输入可以是HV01候选对象或已支持结构域，证据状态照带。R0不要求G1预先通过，因此“还没证明分组增益”不妨碍描述门槛、等待和拒绝；也不允许把候选对象悄悄写成统一共同体。[T-main；T-HV01]","HV02-R0-boundary-inventory在六类边界内容及正式—实际差异可逐项登记时，允许描述边界状态、接口通达、守门位置、拒绝记录、排除风险。上限仅清单和描述，不能断言边界已产生因果选择效应；“选择性开放”作为状态与因果效应已证是不同强度。[T-main]","HV02-R1-selective-effect要求预注册边界或接口变动，经合格G2-instance对指定跨界流、准入/拒绝结果显示超过阈值的通道效应，并追加CAUSAL、E4。其允许结论限指定通道、窗口、位置与跨界成本分布，不从空间/组织/影响范围推出J轴处置权。看见前后变化尚需处理竞争解释和匹配比较。[T-main；T-G2]","边界不等于封闭。一个接口可以对某些信息开放，对另一些资源有资格限制，对不同群体有不同实际可达性；权利责任边界也不必与物理围墙一致。九轴升格要补成员类别、跨域接口、代表授权、保护继承，尤其守门节点变化后要重核谁能拒绝、谁能申诉。[T-main]","状态、可观测和证据共同帮助找到漏点：名单例外、使用记录、流量、拒绝理由、等待时间、正式实际差异各自回答不同问题。无法接入、无法退出、受保护不公开的位置不能从“没有使用记录”推出没有需求或已经同意。[T-main]","输出会接HV05承接、HV07写回和PF-9退出，但接口存在不证明资源到达、坏消息写回或退出安全。获准回滚须纠正成员/拒绝记录、实际恢复相应准入或接口状态、撤销错误动作并验证；不能仅将表中“封闭”改为“开放”。[T-main]","OECD城市可达方法区分站点存在和服务机会可达，可作为形式开放与实际可达差别的局部参照；它没有替这里做预注册G2，不能把方法定义当边界改动因果支持。以下39字段原卡完整保留，按所选路由限制解释。[P-OECD；T-main]","39字段逐项研读（以下“原卡”保留该字段全部内容；“解读”明确其作用和不可替代的责任）。","01｜接口 ID（id）。原卡：HV02 解读：这是卡册内的短标识，追踪同一接口，不表示现实对象已被证明。 [T-main]","02｜限定 ID（qualified_id）。原卡：human_variable:HV02 解读：限定命名空间用于避免同名碰撞；引用此ID仍须携带对象和证据状态。 [T-main]","03｜名称（name）。原卡：边界与接口 解读：名称给出阅读入口，不是对具体人、群体或现实结构的自动标签。 [T-main]","04｜主张类型（claim_type）。原卡：H 解读：H表示人类实例/接口命题的角色；不能把它升级为形式证明或无条件世界规律。 [T-main]","05｜合同角色（contract_role）。原卡：human_variable_interface 解读：这是变量接口合同，规定怎样接入分析；字段存在不等于经验实例已经成立。 [T-main]","06｜命题（proposition）。原卡：人类边界必须同时登记成员、资源、信息、权利、责任与跨界接口。 解读：这条命题必须连同后面的条件路由和上限理解，不能从一句话抽出无条件因果或规范结论。 [T-main]","07｜适用范围（scope）。原卡：存在纳入、排除、交换或管辖的人类结构 解读：范围列出可考察的任务领域，不代表范围内所有对象已获实证支持。 [T-main]","08｜暂停条件（pause_condition）。原卡：正式边界与实际边界混同或排除项不可见 解读：暂停针对所依赖的判断或采用；独立成立的描述可以保留，但不能继续使用失效前提。 [T-main]","09｜推理依赖（inferential_requires）。原卡：1. human_variable:HV01 解读：HV01引用可以携带候选状态；本卡R0不要求G1已通过。不得把上游候选引用隐去证据身份后升级。 [T-main]","10｜协议依赖（protocol_requires）。原卡：1. E1；2. EVIDENCE；3. SOURCE 解读：协议依赖约束取证和表达方式；完成协议不单独证明经验命题为真。 [T-main]","11｜限定／特化（specializes）。原卡：无（空集合） 解读：空集合只说明没有登记这类特化关系，不说明没有证据责任；非空时也不等于普遍有效。 [T-main]","12｜适用对象引用（applies_to）。原卡：无（空集合） 解读：适用对象引用不能代替当前对象合同；空集合是明确登记，不是所有对象都可用。 [T-main]","13｜条件支持路由（conditional_support_routes）。原卡：1. route_id=HV02-R0-boundary-inventory；；claim_level=descriptive_classification；；when=成员、资源、信息、权利、责任、跨界接口及正式—实际边界差异可逐项登记。；；additional_inferential_requires=无（空集合）；；additional_protocol_requires=无（空集合）；；allowed_conclusion=描述边界状态、接口通达性、守门位置、拒绝记录与排除风险。；；result_ceiling=只到边界与接口清单；不得断言边界已产生因果选择效应。；2. route_id=HV02-R1-selective-effect；；claim_level=conditional_effect；；when=预注册边界或接口变动经符合资格的G2-instance显示对指定跨界流、准入或拒绝结果有超过阈值的通道效应。；；additional_inferential_requires=G2-instance；；additional_protocol_requires=CAUSAL、E4；；allowed_conclusion=登记指定通道、窗口与位置上的边界选择效应及跨界成本分布。；；result_ceiling=只限已检验通道与结果；不得从空间、组织或影响范围推出J轴管辖与处置权。 解读：R0只列边界接口，R1须合格预注册G2通道效应并加CAUSAL、E4。两路共享任务对象不等于结论强度相同。 [T-main]","14｜允许推论（allowed_inference）。原卡：1. 边界选择性2. 接口通达性3. 跨界成本 解读：边界选择性、通达性与成本可按R0描述；断言指定通道因果效果时要满足R1，不能只引用此简表越过路由。 [T-main]","15｜禁止跳跃（prohibited_leap）。原卡：1. 边界等于封闭；2. 成员身份等于同意；3. 影响范围等于管辖权 解读：这些是常见越界，不是换个措辞就能避开；检查实际推断和后续使用，而非只看用词。 [T-main]","16｜九轴尺度画像（scale_profile）。原卡：SP=<A,X,T,O,C,R,I,N,J>；A=聚合层次：单次跨界事件、接口使用个案、成员类别总体、准入拒绝分布及聚合规则；X=空间范围：物理入口、组织边界、数字接口、司法辖区与跨域通道；T=时间跨度：边界生效期、接口等待、迁移时滞与重组周期；O=组织层级：使用者角色、守门团队、组织、制度至治理生态；C=因果层次：跨界事件、守门互动机制、接口结构、制度规则与系统条件；R=观察分辨率：原始准入拒绝记录、使用序列、个案、流量分布、服务指标与摘要，并登记压缩损失；I=影响范围：直接使用者、被排除者、间接受益或成本位置、二阶外溢、跨域与代际影响；N=网络拓扑范围：接口节点、守门瓶颈、替代路径与跨域连接；J=管辖与授权范围：纳入、排除、接口改变及权利责任调整分别登记授权；升格须记录逐轴差值 解读：九轴逐项登记；尤其影响范围I不产生管辖权限J，观察分辨率R降低时须保留压缩损失。 [T-main]","17｜有效对象（effective_object）。原卡：对资源、信息、权利或责任流产生选择性的边界 解读：原卡写产生选择性的边界；在R0里应作待描述或待检验对象，不由这一名称先行宣布因果选择效应。 [T-main]","18｜跨尺度保持项（scale_invariants）。原卡：1. 内外位置2. 跨界通道3. 权利责任边界 解读：保持项是迁移时须守住的比较责任，不是宣称所有尺度上的变量数值不变。 [T-main]","19｜升格必补项（required_scale_additions）。原卡：1. 新成员类别；2. 跨域接口；3. 代表与授权；4. 保护继承 解读：升格不是把原表复制放大。新增总体、接口和责任位置等材料未齐时，限制依赖它们的结论。 [T-main]","20｜随尺度改变项（changing_semantics）。原卡：1. 成员、接口与实际控制边界可改变 解读：同一词在对象或尺度改变后可能变义，应重建对应而非假定原含义原样适用。 [T-main]","21｜不适用对象（non_applicable_objects）。原卡：1. 无成员、权利或责任概念的非人边界 解读：不适用约束防止人类规范、责任和体验接口被无条件投射；不等于否认其他理论可研究这些对象。 [T-main]","22｜禁止升格（forbidden_elevation）。原卡：1. 空间或组织范围扩大自动产生管辖权 解读：局部向整体的推断必须另证；影响广、名称大或形式相似都不能补代表性和授权。 [T-main]","23｜状态集合（state）。原卡：1. 开放；2. 选择性开放；3. 封闭；4. 争议；5. 重组 解读：状态是待证描述分类，不是给人评分的成熟阶梯；状态改变须有窗口、依据与版本。 [T-main]","24｜可观测项（observables）。原卡：1. 成员资格、准入与退出决定；2. 资源、信息、权利和责任的跨界流量；3. 守门节点、等待时间与拒绝理由；4. 正式边界与实际通行边界的差异 解读：可观测线索回答到哪里找材料；单一线索的存在还不是完整机制或因果效应的证明。 [T-main]","25｜证据要求（evidence）。原卡：1. 成员名单与例外；2. 接口使用记录；3. 跨界流和拒绝记录 解读：证据清单按路由和任务相关性取得；未知、未收集、不适用、受保护不可得分开，不为填满表强制披露。 [T-main]","26｜输入依赖与接口内容（input_dependencies）。原卡：1. HV01候选对象或已支持结构域及其证据状态；2. 角色与授权；R0不要求G1预先通过 解读：这里说明上游传入什么及其资格；缺口不能在接口间传递时被悄悄抹掉。 [T-main]","27｜输出效应与变量流（output_effects）。原卡：1. HV05承接；2. HV07写回；3. PF-9退出 解读：变量流说明哪些下游判断可能依赖本接口；传递引用不保证下游结论、实际修复或授权成立。 [T-main]","28｜时间窗与时滞（time_window_and_lag）。原卡：记录边界生效、变更、退出和申诉时滞 解读：发生、观察、执行和效果到达可能不同时；窗口外延不能由短期材料自动认证。 [T-main]","29｜不确定性（uncertainty）。原卡：记录非正式边界、代理访问和数字空间漂移 解读：把不确定性指向具体材料和位置，不能只写一个总置信分而掩盖根本未覆盖的位置。 [T-main]","30｜局部排除区（local_exclusion_zone）。原卡：无法接入接口、无法退出或受保护不公开的位置 解读：排除区限制当前推断覆盖，不是把这些人或事实从世界删除；安全不可得也不是同意或无问题。 [T-main]","31｜受影响位置（affected_positions）。原卡：1. 成员；2. 申请者；3. 被排除者；4. 边界外承担者 解读：同时登记直接和间接受影响者；可见成员不代表全部成本承担者。 [T-main]","32｜承接载体（carrier）。原卡：1. 成员规则；2. 访问机制；3. 法律或制度边界；4. 技术接口 解读：载体是实际承载的结构或过程；载体名称、建设完成和所需功能到达是不同证据。 [T-main]","33｜责任主体（responsible_subject）。原卡：1. 边界制定者2. 接口运营者3. 授权者 解读：说明谁提出判断、谁操作或使用；责任登记不自动等于法律责任裁判或新授权。 [T-main]","34｜规范地位（normative_status）。原卡：边界事实与边界正当性分离 解读：按卡片区分描述、规范和桥接身份。事实成立不独立决定价值排序，规范理由不自动证明经验效果。 [T-main]","35｜判断上限（judgment_ceiling）。原卡：接口与影响证据充分时至诊断级 解读：“证据充分时至诊断级”是总上界；R0仍止于清单描述，诊断不能签发改变准入或资源流的权限。 [T-main]","36｜行动上限（action_ceiling）。原卡：本变量只生成边界状态、接口障碍、排除风险与测试需求描述，不授权改变准入、退出、权利或资源流；任何现实调整须另过C12、运行时显式N前提、J授权与O程序 解读：接口本身不产生现实处置权；实际动作另核选择、C12、显式N、有效J、O及保护和期限。 [T-main]","37｜反例（counterexamples）。原卡：1. 正式成员边界与实际资源控制边界相反；2. 数字接口开放但物理、语言或安全门槛使部分位置无法进入 解读：用反例限定无条件外推；反例可能要求缩小范围或重新取证，不自动否定所有有限用法。 [T-main]","38｜申诉（appeal）。原卡：依appeal_and_rollback_rule，边界内外受影响者可经安全可达、反报复通道挑战纳入、排除和接口障碍，并触发与原边界决策链独立的复核 解读：申诉要安全可达、免于报复并能触发独立复核；只留一个名称不代表有权改变错误。 [T-main]","39｜回滚（rollback）。原卡：依appeal_and_rollback_rule，获准回滚时，由指定责任人在规定时限内纠正成员与拒绝记录、实际恢复受影响的准入权利或接口状态并撤销错误边界行动，保留版本与完成验证 解读：在有效授权内实际撤销错误效力、纠正下游并验证完成；文档改字不等于权利资源恢复到当事人。 [T-main]"],"argumentSteps":["以HV01候选或已支持对象固定范围并保留其证据状态。","按成员、资源、信息、权利、责任、接口逐项登记正式与实际差别。","R0先描述门槛和排除；不得把清单当因果效果。","R1另用预注册G2及CAUSAL/E4检验指定通道和结果。","迁移尺度核新成员、跨域接口、代表权限与保护继承。","通过安全独立申诉纠正边界，获准后恢复实际接口与下游记录。"],"distinctions":[{"leftTitle":"正式边界","leftText":"规则或名册如何规定。","rightTitle":"实际边界","rightText":"资源和通行实际如何受控。"},{"leftTitle":"清单描述R0","leftText":"说明谁能到达、被拒和成本。","rightTitle":"通道效应R1","rightText":"预注册G2支持指定改变的因果作用。"},{"leftTitle":"成员身份","leftText":"登记在某种成员集合。","rightTitle":"同意","rightText":"须另核具体事项与真实选择。"},{"leftTitle":"影响范围I","leftText":"边界变化波及何处。","rightTitle":"管辖J","rightText":"由独立有效授权决定。"}],"boundaries":["原卡反例：正式成员边界与实际资源控制边界相反。","原卡反例：数字接口开放而身体、语言或安全门槛阻止部分位置进入。","教学反例：有账号就推定同意所有资料用途。","原文边界：空间扩大不自动增加纳入、排除或资源处置权限。"],"questions":["HV01未有G1支持能否进入HV02？","界面开放是否表示所有人真实可达？","20%变40%是否自动支持R1？","回滚只纠正名册是否足够？"],"diagramPath":"/reading-assets/S-A-2/figures/hv02-routes.png","caseLinks":[{"title":"城市可达指标中的形式与实际差别","href":"https://www.oecd.org/en/publications/transport-bridging-divides_55ae1fd8-en/full-report/component-5.html"}],"caseNotes":[{"title":"城市可达指标中的形式与实际差别","text":"OECD第2章指出有交通站点不保证能到达足够机会，并区分距离口径与时间/交通方式口径。","sourceLabel":"OECD：Transport Bridging Divides，第2章","sourceUrl":"https://www.oecd.org/en/publications/transport-bridging-divides_55ae1fd8-en/full-report/component-5.html","sourceLocator":"Measuring access to opportunities，三指标定义，网页行3869—3877","boundary":"仅为可达性概念和测量对照，不是本卡G2实例，也不证明某项准入或管辖安排正当。","href":"https://www.oecd.org/en/publications/transport-bridging-divides_55ae1fd8-en/full-report/component-5.html"}],"sourceRefs":[{"section":"A.2","start_line":3634,"end_line":3699,"startLine":3634,"endLine":3699}],"outputId":"section-a-2","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","teachingExamples":[{"title":"教学构造：开放网址与实际通行","text":"虚构服务网页所有人都能打开，但提交需某种证件，唯一支持语言又非部分使用者可理解。R0可列网页、资格、语言三处边界以及未知受影响位置；不能由“可打开”宣布全员可达，也不能未经测试说取消某项门槛一定带来多少效果。","assumptions":"人工服务情景，无实际个人资料或资格决定。","boundary":"描述门槛不授权更改准入；规范正当性和因果作用另核。"},{"title":"教学构造：前后数值不是自动G2","text":"人工接口变动前100次申请中20次成功，之后100次中40次成功，观察成功比例由20%到40%，相差20个百分点。若申请者构成、需求或其他流程同时改变，差值不能单独归因该接口。申请R1还须合格预注册G2及比较、阈值、窗口和证据规则；这里没有正式supported。","assumptions":"数字完全教学，两个100不保证同一总体或有效比较。","boundary":"相关或前后差异不替代因果合同，改门槛也须独立权限。"}],"counterexamples":[{"identity":"source_counterexample","text":"原卡反例：正式成员边界与实际资源控制边界相反。","effect":"限制本节的无条件延伸；不否定具有独立依据的有限判断。","sourceIds":["T-main"]},{"identity":"source_counterexample","text":"原卡反例：数字接口开放而身体、语言或安全门槛阻止部分位置进入。","effect":"限制本节的无条件延伸；不否定具有独立依据的有限判断。","sourceIds":["T-main"]},{"identity":"constructed_boundary","text":"教学反例：有账号就推定同意所有资料用途。","effect":"限制本节的无条件延伸；不否定具有独立依据的有限判断。","sourceIds":["T-main"]},{"identity":"source_counterexample","text":"原文边界：空间扩大不自动增加纳入、排除或资源处置权限。","effect":"限制本节的无条件延伸；不否定具有独立依据的有限判断。","sourceIds":["T-main"]}],"questionAnswers":[{"question":"HV01未有G1支持能否进入HV02？","answer":"可以用候选对象引用走R0，保留边界和不确定性。","basis":"input_dependencies及R0。"},{"question":"界面开放是否表示所有人真实可达？","answer":"不；要核物理语言安全、资格和实际接口记录。","basis":"反例及observables。"},{"question":"20%变40%是否自动支持R1？","answer":"不是；前后差异还需相称G2因果比较与预注册规则。","basis":"R1条件与CAUSAL。"},{"question":"回滚只纠正名册是否足够？","answer":"须按有效范围实际恢复受影响准入/接口，纠正记录并验证完成。","basis":"rollback。"}],"figures":[{"path":"/reading-assets/S-A-2/figures/hv02-routes.png","alt":"R0边界清单不需G1预先通过；R1须G2指定通道效应及CAUSAL/E4；两路都不授处置权。","caption":"据A.2完整条件路由。"},{"path":"/reading-assets/S-A-2/figures/hv02-interfaces.png","alt":"成员资源信息权利责任跨界接口分别核正式与实际边界，弱势缺席位置与回滚效果不能省。","caption":"据A.2 C—E区。"}],"diagramBrief":"两图分别显示路由分离和六类边界接口；不把开放/封闭排成好坏等级，先核具体对象与后果。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"本单元涉及方法判断，真实来源仅支持所列事实；图与教学构造分别保留其身份。"},"openQuestions":["无真实G2-instance；教学前后比例只展示归因缺口。","具体边界正当性、管辖权限、排除者影响与实际恢复需现场和独立程序材料。"],"taskId":"S-A-2","sources":[{"id":"T-main","title":"Xikari著《Xikari-条件结构与转化论》","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68；文本自述2026年10月","locator":"§A.2，第3634—3699行","claim_support":["HV02全部39字段，R0描述/R1通道效果与上限。"],"limits":["支持当前稿的文本含义与明确限定的推理；不自行证明经验普遍性、实施效果或读者学习成效。"],"access_status":"read"},{"id":"T-HV01","title":"Xikari著《Xikari-条件结构与转化论》","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68；文本自述2026年10月","locator":"§A.1，第3568—3633行","claim_support":["候选引用可传下游且保留状态。"],"limits":["支持当前稿的文本含义与明确限定的推理；不自行证明经验普遍性、实施效果或读者学习成效。"],"access_status":"read"},{"id":"T-G2","title":"Xikari著《Xikari-条件结构与转化论》","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68；文本自述2026年10月","locator":"§4.4，第610—619行","claim_support":["G2指定通道效应与有限性。"],"limits":["支持当前稿的文本含义与明确限定的推理；不自行证明经验普遍性、实施效果或读者学习成效。"],"access_status":"read"},{"id":"P-OECD","title":"OECD：Transport Bridging Divides，第2章","url":"https://www.oecd.org/en/publications/transport-bridging-divides_55ae1fd8-en/full-report/component-5.html","source_type":"primary","version_or_date":"2020年报告；2026-10-14读取","locator":"Measuring access to opportunities，三指标定义，网页行3869—3877","claim_support":["站点存在与机会可达不同，距离与给定时间/方式的可达指标分别定义。"],"limits":["本人局部读该栏目；不证明某边界改变的因果效应，也不测每个使用者的语言、费用、身体或安全门槛。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-A-2/lecture.md","sourcesPath":"/reading-assets/S-A-2/sources.json","sourceSlicePath":"/reading-assets/S-A-2/source/S-A-2.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-A-2/diagrams.md"}}},"headers":[],"relativePath":"theory/appendix-a/a-02.md","filePath":"theory/appendix-a/a-02.md"}'),l={name:"theory/appendix-a/a-02.md"};function c(_,t,p,u,b,m){const e=a("SectionLesson");return r(),d("div",null,[t[0]||(t[0]=n('<div class="theory-source"><h1 id="section-a-2" tabindex="-1"><span class="xk-num"><span class="xk-num__n">A.2</span><span class="xk-num__gap">　</span></span>HV02 边界与接口（完整接口卡） <a class="header-anchor" href="#section-a-2" aria-label="Permalink to &quot;A.2　HV02 边界与接口（完整接口卡） {#section-a-2}&quot;">​</a></h1><p>A. 身份、命题与适用范围</p><div class="xk-table"><table><thead><tr><th>字段</th><th>登记内容</th></tr></thead><tbody><tr><td>接口 ID（id）</td><td>HV02</td></tr><tr><td>限定 ID（qualified_id）</td><td>human_variable:HV02</td></tr><tr><td>名称（name）</td><td>边界与接口</td></tr><tr><td>主张类型（claim_type）</td><td>H</td></tr><tr><td>合同角色（contract_role）</td><td>human_variable_interface</td></tr><tr><td>命题（proposition）</td><td>人类边界必须同时登记成员、资源、信息、权利、责任与跨界接口。</td></tr><tr><td>适用范围（scope）</td><td>存在纳入、排除、交换或管辖的人类结构</td></tr><tr><td>暂停条件（pause_condition）</td><td>正式边界与实际边界混同或排除项不可见</td></tr></tbody></table></div><p>B. 正式依赖与结论边界</p><div class="xk-table"><table><thead><tr><th>字段</th><th>登记内容</th></tr></thead><tbody><tr><td>推理依赖（inferential_requires）</td><td>1. human_variable:HV01</td></tr><tr><td>协议依赖（protocol_requires）</td><td>1. E1<br>2. EVIDENCE<br>3. SOURCE</td></tr><tr><td>限定／特化（specializes）</td><td>无（空集合）</td></tr><tr><td>适用对象引用（applies_to）</td><td>无（空集合）</td></tr><tr><td>条件支持路由（conditional_support_routes）</td><td>1. route_id=HV02-R0-boundary-inventory；<br>claim_level=descriptive_classification；<br>when=成员、资源、信息、权利、责任、跨界接口及正式—实际边界差异可逐项登记。；<br>additional_inferential_requires=无（空集合）；<br>additional_protocol_requires=无（空集合）；<br>allowed_conclusion=描述边界状态、接口通达性、守门位置、拒绝记录与排除风险。；<br>result_ceiling=只到边界与接口清单；不得断言边界已产生因果选择效应。<br>2. route_id=HV02-R1-selective-effect；<br>claim_level=conditional_effect；<br>when=预注册边界或接口变动经符合资格的G2-instance显示对指定跨界流、准入或拒绝结果有超过阈值的通道效应。；<br>additional_inferential_requires=G2-instance；<br>additional_protocol_requires=CAUSAL、E4；<br>allowed_conclusion=登记指定通道、窗口与位置上的边界选择效应及跨界成本分布。；<br>result_ceiling=只限已检验通道与结果；不得从空间、组织或影响范围推出J轴管辖与处置权。</td></tr><tr><td>允许推论（allowed_inference）</td><td>1. 边界选择性2. 接口通达性3. 跨界成本</td></tr><tr><td>禁止跳跃（prohibited_leap）</td><td>1. 边界等于封闭<br>2. 成员身份等于同意<br>3. 影响范围等于管辖权</td></tr></tbody></table></div><p>C. 九轴尺度与对象合同</p><div class="xk-table"><table><thead><tr><th>字段</th><th>登记内容</th></tr></thead><tbody><tr><td>九轴尺度画像（scale_profile）</td><td>SP=&lt;A,X,T,O,C,R,I,N,J&gt;；A=聚合层次：单次跨界事件、接口使用个案、成员类别总体、准入拒绝分布及聚合规则；X=空间范围：物理入口、组织边界、数字接口、司法辖区与跨域通道；T=时间跨度：边界生效期、接口等待、迁移时滞与重组周期；O=组织层级：使用者角色、守门团队、组织、制度至治理生态；C=因果层次：跨界事件、守门互动机制、接口结构、制度规则与系统条件；R=观察分辨率：原始准入拒绝记录、使用序列、个案、流量分布、服务指标与摘要，并登记压缩损失；I=影响范围：直接使用者、被排除者、间接受益或成本位置、二阶外溢、跨域与代际影响；N=网络拓扑范围：接口节点、守门瓶颈、替代路径与跨域连接；J=管辖与授权范围：纳入、排除、接口改变及权利责任调整分别登记授权；升格须记录逐轴差值</td></tr><tr><td>有效对象（effective_object）</td><td>对资源、信息、权利或责任流产生选择性的边界</td></tr><tr><td>跨尺度保持项（scale_invariants）</td><td>1. 内外位置2. 跨界通道3. 权利责任边界</td></tr><tr><td>升格必补项（required_scale_additions）</td><td>1. 新成员类别<br>2. 跨域接口<br>3. 代表与授权<br>4. 保护继承</td></tr><tr><td>随尺度改变项（changing_semantics）</td><td>1. 成员、接口与实际控制边界可改变</td></tr><tr><td>不适用对象（non_applicable_objects）</td><td>1. 无成员、权利或责任概念的非人边界</td></tr><tr><td>禁止升格（forbidden_elevation）</td><td>1. 空间或组织范围扩大自动产生管辖权</td></tr></tbody></table></div><p>D. 状态、证据与变量流</p><div class="xk-table"><table><thead><tr><th>字段</th><th>登记内容</th></tr></thead><tbody><tr><td>状态集合（state）</td><td>1. 开放<br>2. 选择性开放<br>3. 封闭<br>4. 争议<br>5. 重组</td></tr><tr><td>可观测项（observables）</td><td>1. 成员资格、准入与退出决定<br>2. 资源、信息、权利和责任的跨界流量<br>3. 守门节点、等待时间与拒绝理由<br>4. 正式边界与实际通行边界的差异</td></tr><tr><td>证据要求（evidence）</td><td>1. 成员名单与例外<br>2. 接口使用记录<br>3. 跨界流和拒绝记录</td></tr><tr><td>输入依赖与接口内容（input_dependencies）</td><td>1. HV01候选对象或已支持结构域及其证据状态<br>2. 角色与授权；R0不要求G1预先通过</td></tr><tr><td>输出效应与变量流（output_effects）</td><td>1. HV05承接<br>2. HV07写回<br>3. PF-9退出</td></tr><tr><td>时间窗与时滞（time_window_and_lag）</td><td>记录边界生效、变更、退出和申诉时滞</td></tr><tr><td>不确定性（uncertainty）</td><td>记录非正式边界、代理访问和数字空间漂移</td></tr><tr><td>局部排除区（local_exclusion_zone）</td><td>无法接入接口、无法退出或受保护不公开的位置</td></tr><tr><td>受影响位置（affected_positions）</td><td>1. 成员<br>2. 申请者<br>3. 被排除者<br>4. 边界外承担者</td></tr></tbody></table></div><p>E. 承接、责任、规范、上限与纠错</p><div class="xk-table"><table><thead><tr><th>字段</th><th>登记内容</th></tr></thead><tbody><tr><td>承接载体（carrier）</td><td>1. 成员规则<br>2. 访问机制<br>3. 法律或制度边界<br>4. 技术接口</td></tr><tr><td>责任主体（responsible_subject）</td><td>1. 边界制定者2. 接口运营者3. 授权者</td></tr><tr><td>规范地位（normative_status）</td><td>边界事实与边界正当性分离</td></tr><tr><td>判断上限（judgment_ceiling）</td><td>接口与影响证据充分时至诊断级</td></tr><tr><td>行动上限（action_ceiling）</td><td>本变量只生成边界状态、接口障碍、排除风险与测试需求描述，不授权改变准入、退出、权利或资源流；任何现实调整须另过C12、运行时显式N前提、J授权与O程序</td></tr><tr><td>反例（counterexamples）</td><td>1. 正式成员边界与实际资源控制边界相反<br>2. 数字接口开放但物理、语言或安全门槛使部分位置无法进入</td></tr><tr><td>申诉（appeal）</td><td>依appeal_and_rollback_rule，边界内外受影响者可经安全可达、反报复通道挑战纳入、排除和接口障碍，并触发与原边界决策链独立的复核</td></tr><tr><td>回滚（rollback）</td><td>依appeal_and_rollback_rule，获准回滚时，由指定责任人在规定时限内纠正成员与拒绝记录、实际恢复受影响的准入权利或接口状态并撤销错误边界行动，保留版本与完成验证</td></tr></tbody></table></div></div>',1)),s(e,{section:"A.2"}),t[1]||(t[1]=o("div",{class:"theory-source"},null,-1))])}const T=i(l,[["render",c]]);export{f as __pageData,T as default};
